def clamp_lower(value, lower_bound):
    return max(value, lower_bound)

def clamp_upper(value, upper_bound):
    return min(value, upper_bound)

def clamp(value, lower_bound, upper_bound):
    return min(max(value, lower_bound), upper_bound)

def calculate_wcrt_constrained(task_k, chi_value):
    return chi_value

def calculate_wcrt_arbitrary(task_k, chi_values_list, H):
    max_response_time = 0
    for h in range(1, H + 1):
        # R_h_k = chi_h - (h - 1) * task_k.T (from paper, Lemma 5)
        R_h_k = chi_values_list[h-1] - (h - 1) * task_k.T
        if R_h_k > max_response_time:
            max_response_time = R_h_k
    return max_response_time

def calculate_I_NC_k(tau_i, x, C_k, R_i_hp):
    W_NC_k_val, _ = calculate_workload_bounds(tau_i, x, R_i_hp) # R_i_hp is WCRT of tau_i
    return min(max(W_NC_k_val, 0), x - C_k + 1)

def calculate_I_CI_k(tau_i, x, C_k, R_i_hp):
    _, W_CI_k_val = calculate_workload_bounds(tau_i, x, R_i_hp) # R_i_hp is WCRT of tau_i
    return min(max(W_CI_k_val, 0), x - C_k + 1)

def calculate_I_NC_k_h(tau_i, x, h, C_k, R_i_hp):
    W_NC_k_val, _ = calculate_workload_bounds(tau_i, x, R_i_hp)
    return min(max(W_NC_k_val, 0), x - h * C_k + 1)

def calculate_I_CI_k_h(tau_i, x, h, C_k, R_i_hp):
    _, W_CI_k_val = calculate_workload_bounds(tau_i, x, R_i_hp)
    return min(max(W_CI_k_val, 0), x - h * C_k + 1)

def calculate_Omega_k_h(task_k, x, h, task_set_hp_k, M, R_hp_map):
    interferences = []
    for tau_i in task_set_hp_k:
        R_i_hp = R_hp_map.get(tau_i.id, 0)
        I_NC_k_h_val = calculate_I_NC_k_h(tau_i, x, h, task_k.C, R_i_hp)
        I_CI_k_h_val = calculate_I_CI_k_h(tau_i, x, h, task_k.C, R_i_hp)
        interferences.append({
            'task': tau_i,
            'I_NC': I_NC_k_h_val,
            'I_CI': I_CI_k_h_val,
            'delta_I': I_CI_k_h_val - I_NC_k_h_val
        })

    interferences.sort(key=lambda item: item['delta_I'], reverse=True)

    total_interference = 0
    num_carry_in_assigned = 0

    for item in interferences:
        if num_carry_in_assigned < M - 1 and item['delta_I'] > 0:
            total_interference += item['I_CI']
            num_carry_in_assigned += 1
        else:
            total_interference += item['I_NC']

    return total_interference

def check_lemma_3(Omega_k_val, M, x, C_k):
    # This lemma is used in the proof of Lemma 4, not directly in the algorithm.
    # It implies that if Omega_k(x) / M + C_k > x, then x is not the response time.
    return (Omega_k_val / M) > (x - C_k)

def calculate_chi_for_phi(task_k, task_set_hp_k, M, phi, R_hp_map):
    x_current = task_k.C
    while True:
        Omega_k_val = calculate_Omega_k(task_k, x_current, task_set_hp_k, M, R_hp_map)
        x_next = Omega_k_val / M + task_k.C
        if x_next == x_current:
            return x_next
        if x_next > task_k.D + phi: # Check against deadline relative to t_0
            return float('inf') # Unschedulable
        x_current = x_next

def calculate_response_time_for_phi(task_k, task_set_hp_k, M, phi, R_hp_map):
    chi = calculate_chi_for_phi(task_k, task_set_hp_k, M, phi, R_hp_map)
    if chi == float('inf'):
        return float('inf')
    return chi - phi

def OUR_RTA_constrained(task_k, task_set_hp_k, M, R_hp_map):
    x_current = task_k.C
    while True:
        Omega_k_val = calculate_Omega_k(task_k, x_current, task_set_hp_k, M, R_hp_map)
        x_next = Omega_k_val / M + task_k.C

        if x_next == x_current:
            return x_next # chi is found

        if x_next > task_k.D:
            return float('inf') # Deadline miss detected

        x_current = x_next

def calculate_chi_h_for_phi(task_k, h, task_set_hp_k, M, R_hp_map):
    x_current = h * task_k.C
    while True:
        Omega_k_h_val = calculate_Omega_k_h(task_k, x_current, h, task_set_hp_k, M, R_hp_map)
        x_next = Omega_k_h_val / M + h * task_k.C
        if x_next == x_current:
            return x_next
        # Check for deadline miss during fixed point search (x > (h-1)*T_k + D_k + phi)
        if x_next > (h - 1) * task_k.T + task_k.D + phi:
            return float('inf') # Unschedulable
        x_current = x_next

def calculate_R_phi_k(task_k, task_set_hp_k, M, phi, R_hp_map):
    chi_values = []
    h = 1
    H_phi = float('inf')
    while True:
        chi_h = calculate_chi_h_for_phi(task_k, h, task_set_hp_k, M, R_hp_map)
        if chi_h == float('inf'):
            return float('inf') # Unschedulable
        chi_values.append(chi_h)

        if chi_h <= h * task_k.T + phi:
            H_phi = h
            break
        h += 1

    max_response_time = 0
    for idx in range(H_phi):
        R_h_k = chi_values[idx] - (idx) * task_k.T - phi
        if R_h_k > max_response_time:
            max_response_time = R_h_k

    return max_response_time

def check_termination_condition(task_k, task_set_hp_k, M):
    sum_V_k_i = 0
    for tau_i in task_set_hp_k:
        sum_V_k_i += calculate_V_k_i(tau_i, task_k)

    return sum_V_k_i + M * task_k.U < M

